//! Golden vectors for token format v3: `tests/v3_vectors.json`.
//!
//! The file is GENERATED by this test from fixed seeds (Ed25519 and RFC 6979 P-256 are
//! deterministic, so the output is stable). The cases are the three chains of
//! `docs/CAPABILITY-PROGRAMS.md` sections 12.1 to 12.3 (`v3/cases.rs`), refusals of each
//! (`v3/negative.rs`), and the condition chains of section 12.4: `Requires`, `CoSign` and `Via`,
//! each met and each refused, and children that drop an inherited condition (`v3/conditions.rs`).
//! Each case states the outcome it must have; generation fails if the code disagrees. On every run
//! the test regenerates the vectors in memory and asserts they equal the committed file, then
//! re-runs every vector from the FILE alone. Regenerate after an intentional change with
//! `CE_NET_PROTO_REGEN=1 cargo test --test v3_vectors`.

#[path = "v3/cases.rs"]
mod cases;
#[path = "v3/conditions.rs"]
mod conditions;
#[path = "v3/negative.rs"]
mod negative;

use std::collections::HashSet;

use ce_net_proto::program::{Hash, Step};
use ce_net_proto::v3::uses::BurnLog;
use ce_net_proto::v3::verify::{Node, OwnerRoot, Presented, Request, Roots, authorize_use_v3, authorize_v3, verify_chain_v3};
use ce_net_proto::v3::{Key, Link, Sig, TokenV3, UseRequest, cap_bytes, cap_id, cosign_bytes, decode_proofs, encode_proofs, request_id, via_bytes};
use serde_json::{Value, json};

use cases::*;

const PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/v3_vectors.json");

fn h(b: &[u8]) -> String {
    hex::encode(b)
}

fn key_json(k: &Key) -> Value {
    match k {
        Key::Ed25519(b) => json!({ "type": "Ed25519", "public": h(b) }),
        Key::P256(b) => json!({ "type": "P256", "public": h(b) }),
    }
}

fn key_of(v: &Value) -> Key {
    let b = hex::decode(v["public"].as_str().unwrap()).unwrap();
    match v["type"].as_str().unwrap() {
        "Ed25519" => Key::Ed25519(b.try_into().unwrap()),
        _ => Key::P256(b.try_into().unwrap()),
    }
}

fn hash_of(v: &Value) -> Hash {
    hex::decode(v.as_str().unwrap()).unwrap().try_into().unwrap()
}

fn sig_json(s: &Sig) -> Value {
    match s {
        Sig::Ed25519(b) => json!({ "type": "Ed25519", "hex": h(b) }),
        Sig::P256(b) => json!({ "type": "P256", "hex": h(b) }),
        Sig::WebAuthn { .. } => json!({ "type": "WebAuthn", "hex": h(&bincode::serialize(s).unwrap()) }),
    }
}

fn result(r: Result<Value, String>) -> Value {
    match r {
        Ok(mut v) => {
            v["ok"] = json!(true);
            v
        }
        Err(e) => json!({ "ok": false, "error": e }),
    }
}

fn request_json(r: &Req) -> Value {
    match r {
        Req::Call(a) => json!({ "call": a }),
        Req::Exec { program, run, step, req } => {
            json!({ "execute": { "program": h(program), "run": run, "step": step, "req": h(&bincode::serialize(req).unwrap()) } })
        }
    }
}

/// The inputs of one case, as the file carries them.
fn inputs(c: &Case) -> Value {
    let uses: Vec<Value> = c
        .uses
        .iter()
        .map(|u| {
            json!({
                "node": { "id": h(&node(u.at.seed)), "host": u.at.host },
                "requester": key_json(&key(u.requester)),
                "token_hex": u.token.as_ref().map(|t| h(t)),
                "request": request_json(&u.req),
                "presented": u.shown.as_ref().map(|p| json!({
                    "use_request": use_request_json(&p.request),
                    "use_request_hex": h(&bincode::serialize(&p.request).unwrap()),
                    "proofs_hex": h(&encode_proofs(&p.proofs)),
                    "body_hex": h(&p.body),
                })),
            })
        })
        .collect();
    let cells: Vec<Value> = c.cells.iter().map(|(api, seed)| json!({ "api": api, "keys": [key_json(&key(*seed))] })).collect();
    json!({
        "name": c.name,
        "note": c.note,
        "token_hex": h(&c.token),
        "roots": { "keys": [], "owners": [{ "key": key_json(&key(LEIF)), "rp_id": null, "not_before": 0, "not_after": 0 }] },
        "now": c.now,
        "cell_keys": cells,
        "uses": uses,
    })
}

/// A `UseRequest` field by field, for a reader; a verifier decodes `use_request_hex`.
fn use_request_json(r: &UseRequest) -> Value {
    json!({ "leaf": h(&r.leaf), "node": h(&r.node), "requester": key_json(&r.requester), "action": r.action, "body": h(&r.body), "at": r.at, "nonce": r.nonce })
}

/// One use that presents a request and proofs (section 4.1), as a node runs it: the proofs are
/// decoded strictly, the body is hashed here, and `seen` is the node's replay log.
#[allow(clippy::too_many_arguments)]
fn authorize_shown(p: &Value, cells: &Value, seen: &mut HashSet<Hash>, node: &Node, roots: &Roots, now: u64, who: &Key, req: &Request, t: &TokenV3, burn: &mut dyn FnMut(&ce_net_proto::v3::verify::Charge) -> Result<(), String>) -> Value {
    let bytes = |k: &str| hex::decode(p[k].as_str().unwrap()).unwrap();
    let request: UseRequest = bincode::deserialize(&bytes("use_request_hex")).unwrap();
    let signed = json!({ "request_id": h(&request_id(&request)), "cosign_bytes": h(&cosign_bytes(&request)), "via_bytes": h(&via_bytes(&request)) });
    let cell_keys = |api: &str| -> Vec<Key> {
        let known = cells.as_array().unwrap().iter().find(|c| c["api"] == api);
        known.map_or(vec![], |c| c["keys"].as_array().unwrap().iter().map(key_of).collect())
    };
    let mut first_use = |id: &Hash, _forget_after: u64| if seen.insert(*id) { Ok(()) } else { Err("request replayed".to_string()) };
    let got = decode_proofs(&bytes("proofs_hex")).map_err(|e| e.0).and_then(|proofs| {
        let body: Hash = sha(&bytes("body_hex"));
        let mut used = Presented { request: &request, proofs: &proofs, body, cell_keys: &cell_keys, first_use: &mut first_use };
        authorize_use_v3(node, roots, now, who, req, t, &mut used, &never, burn)
    });
    let mut r = result(got.map(|_| json!({})));
    r["signed"] = signed;
    r
}

fn never(_: &Key, _: u64) -> bool {
    false
}

/// Everything a verifier derives from a case's inputs: the decoded links and programs, the
/// `verify_chain_v3` result and each use's `authorize_v3` result, in order against one fresh burn
/// log per node.
fn evaluate(c: &Value) -> Value {
    let keys: Vec<Key> = c["roots"]["keys"].as_array().unwrap().iter().map(key_of).collect();
    let owners: Vec<OwnerRoot> = c["roots"]["owners"]
        .as_array()
        .unwrap()
        .iter()
        .map(|o| OwnerRoot {
            key: key_of(&o["key"]),
            rp_id: o["rp_id"].as_str().map(str::to_string),
            not_before: o["not_before"].as_u64().unwrap(),
            not_after: o["not_after"].as_u64().unwrap(),
        })
        .collect();
    let roots = Roots { keys: &keys, owners: &owners };
    let now = c["now"].as_u64().unwrap();
    let t = match TokenV3::from_hex(c["token_hex"].as_str().unwrap()) {
        Ok(t) => t,
        Err(e) => return json!({ "links": [], "programs": [], "verify": result(Err(e.0)), "uses": [] }),
    };
    let links: Vec<Value> = t
        .links
        .iter()
        .map(|l| match l {
            Link::V3 { cap, sig } => json!({
                "issuer": key_json(&cap.issuer), "audience": key_json(&cap.audience), "nonce": cap.nonce,
                "cap_bytes": h(&cap_bytes(cap)), "cap_id": h(&cap_id(cap)), "sig": sig_json(sig),
            }),
            Link::V1(s) => json!({ "v1_cap_id": h(&s.id()) }),
        })
        .collect();
    let programs: Vec<Value> = t.programs.iter().map(|p| json!({ "id": h(&p.id()), "bytes": h(&p.encode()) })).collect();
    let verify = verify_chain_v3(&t, &roots, now, &never)
        .map(|v| json!({ "holder": key_json(&v.holder), "leaf": h(&v.leaf()), "counted": v.counted.len() }));
    static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let seq = SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let dir = std::env::temp_dir().join(format!("ce-net-proto-v3-vectors-{}-{seq}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let mut logs: Vec<(Hash, BurnLog, HashSet<Hash>)> = Vec::new();
    let mut uses = Vec::new();
    for u in c["uses"].as_array().unwrap() {
        let id = hash_of(&u["node"]["id"]);
        if !logs.iter().any(|(n, ..)| n == &id) {
            logs.push((id, BurnLog::open(&dir.join(format!("{}.burn", h(&id[..8])))).unwrap(), HashSet::new()));
        }
        let (_, log, seen) = logs.iter_mut().find(|(n, ..)| n == &id).unwrap();
        let ut = u["token_hex"].as_str().map(|s| TokenV3::from_hex(s).unwrap());
        let host = u["node"]["host"].as_str();
        let node = Node { id, tags: &[], host };
        let r = &u["request"];
        let step: Option<Step> = r["execute"]["req"].as_str().map(|s| bincode::deserialize(&hex::decode(s).unwrap()).unwrap());
        let req = match &step {
            Some(st) => {
                let e = &r["execute"];
                let run = e["run"].as_u64().unwrap() as u32;
                Request::Execute { program: hash_of(&e["program"]), run, step: e["step"].as_u64().unwrap() as u32, req: st }
            }
            None => Request::Call(r["call"].as_str().unwrap()),
        };
        let mut burn = log.burner(id, now);
        let (who, t) = (key_of(&u["requester"]), ut.as_ref().unwrap_or(&t));
        uses.push(match &u["presented"] {
            Value::Null => result(authorize_v3(&node, &roots, now, &who, &req, t, &never, &mut burn).map(|_| json!({}))),
            p => authorize_shown(p, &c["cell_keys"], seen, &node, &roots, now, &who, &req, t, &mut burn),
        });
    }
    drop(logs);
    let _ = std::fs::remove_dir_all(&dir);
    json!({ "links": links, "programs": programs, "verify": result(verify), "uses": uses })
}

fn check_want(name: &str, what: &str, got: &Value, want: &Result<(), &str>) {
    match want {
        Ok(()) => assert_eq!(got["ok"], json!(true), "{name} {what}: expected success, got {got}"),
        Err(s) => {
            let e = got["error"].as_str().unwrap_or_else(|| panic!("{name} {what}: expected refusal '{s}', got {got}"));
            assert!(e.contains(s), "{name} {what}: expected refusal containing '{s}', got '{e}'");
        }
    }
}

fn generate() -> Value {
    let mut out = Vec::new();
    for c in cases::positive().into_iter().chain(negative::negative()).chain(conditions::conditions()) {
        let mut v = inputs(&c);
        let e = evaluate(&v);
        check_want(c.name, "verify", &e["verify"], &c.verify);
        assert_eq!(e["uses"].as_array().unwrap().len(), c.uses.len(), "{}: uses not run", c.name);
        for (i, u) in c.uses.iter().enumerate() {
            check_want(c.name, &format!("use {i}"), &e["uses"][i], &u.want);
        }
        v["expect"] = e;
        out.push(v);
    }
    json!({
        "format": "ce-net-proto capability vectors v3 (docs/CAPABILITY-PROGRAMS.md)",
        "generated_by": "cargo test --test v3_vectors (CE_NET_PROTO_REGEN=1 to rewrite)",
        "keys": KEYS.iter().map(|(name, seed)| json!({ "name": name, "seed": h(&[*seed; 32]), "key": key_json(&key(*seed)) })).collect::<Vec<_>>(),
        "T": T,
        "vectors": out,
    })
}

/// The vectors as generated now, and the file as it is on disk. Asked once per test run, so a
/// regeneration (`CE_NET_PROTO_REGEN`, or no file yet) is done before either test reads the file.
fn generated_and_file() -> &'static (String, String) {
    static BOTH: std::sync::OnceLock<(String, String)> = std::sync::OnceLock::new();
    BOTH.get_or_init(|| {
        let text = serde_json::to_string_pretty(&generate()).unwrap() + "\n";
        if std::env::var_os("CE_NET_PROTO_REGEN").is_some() || !std::path::Path::new(PATH).exists() {
            std::fs::write(PATH, &text).unwrap();
        }
        (text, std::fs::read_to_string(PATH).unwrap())
    })
}

#[test]
fn v3_vectors_file_matches_generator() {
    let (text, on_disk) = generated_and_file();
    assert!(on_disk == text, "tests/v3_vectors.json is stale; rerun with CE_NET_PROTO_REGEN=1");
}

/// `docs/CAPABILITY-PROGRAMS.md` section 12.5 quotes these vectors: every key, the program ids and
/// link ids of each chain it tabulates, the request id of each allowed use that presents proofs,
/// and the whole Raspberry Pi token. A regeneration that changes them must change the document.
#[test]
fn v3_vectors_are_the_bytes_the_spec_quotes() {
    let v: Value = serde_json::from_str(&generated_and_file().1).unwrap();
    let doc = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/docs/CAPABILITY-PROGRAMS.md")).unwrap().replace('\n', "");
    let quoted = |what: &str, hex: &Value| assert!(doc.contains(hex.as_str().unwrap()), "section 12.5 does not quote {what} {hex}");
    for k in v["keys"].as_array().unwrap() {
        quoted("the key", &k["key"]["public"]);
    }
    for c in v["vectors"].as_array().unwrap().iter().filter(|c| ALLOWED.contains(&c["name"].as_str().unwrap()) || c["name"] == "long-process-key") {
        let name = c["name"].as_str().unwrap();
        for l in c["expect"]["links"].as_array().unwrap() {
            quoted(name, &l["cap_id"]);
        }
        for p in c["expect"]["programs"].as_array().unwrap() {
            quoted(name, &p["id"]);
        }
        for u in c["expect"]["uses"].as_array().unwrap().iter().filter(|u| u["ok"] == json!(true) && !u["signed"].is_null()) {
            quoted(name, &u["signed"]["request_id"]);
        }
    }
    quoted("the 12.1 token", &v["vectors"][0]["token_hex"]);
}

/// Vectors this suite promises in which the chain verifies and a use is allowed.
const ALLOWED: &[&str] = &[
    "pi-install-once",
    "long-agent-runs-twice",
    "first-use-six-installs",
    "wechat-read-then-write",
    "guardian-approves-and-brokers",
    "printer-through-its-agent",
    "printer-child-adds-guardian",
];

/// Vectors this suite promises in which the chain, or a use of it, is refused.
const REFUSED: &[&str] = &[
    "pi-widened-ability",
    "pi-widened-resource",
    "long-l1-depth-not-dropping",
    "pi-wrong-audience",
    "pi-wrong-program",
    "pi-replayed",
    "pi-unknown-caveat-variant",
    "pi-expired",
    "long-l0-widened-after-signing",
    "long-l1-widened-egress",
    "long-l2-widened-egress",
    "wechat-write-unread",
    "guardian-not-asked",
    "guardian-approval-replayed",
    "printer-around-its-agent",
    "wechat-child-drops-requires",
    "guardian-child-drops-via",
];

/// Every vector from the FILE (not the generator): decode, verify and authorize reproduce `expect`,
/// and each promised vector is there with the outcome promised.
#[test]
fn v3_vectors_replay_from_file() {
    let v: Value = serde_json::from_str(&generated_and_file().1).unwrap();
    let (mut allowed, mut refused) = (Vec::new(), Vec::new());
    for c in v["vectors"].as_array().unwrap() {
        assert_eq!(evaluate(c), c["expect"], "{}", c["name"]);
        let (name, e) = (c["name"].as_str().unwrap(), &c["expect"]);
        let verified = e["verify"]["ok"] == json!(true);
        let uses = e["uses"].as_array().unwrap();
        if verified && uses.iter().any(|u| u["ok"] == json!(true)) {
            allowed.push(name);
        }
        if !verified || uses.iter().any(|u| u["ok"] != json!(true)) {
            refused.push(name);
        }
    }
    for want in ALLOWED {
        assert!(allowed.contains(want), "vector {want} is missing or allows no use");
    }
    for want in REFUSED {
        assert!(refused.contains(want), "vector {want} is missing or refuses nothing");
    }
}
